""" Main entry point.
High-level wiring of components per CMP--10 (Scheduler and Initialization). """
from core.scheduler import Scheduler # CMP--10 from core.sensor_layer import SensorAbstractionLayer # CMP--7 from core.gridmap import GridMap # CMP--3 from core.mapping import MappingModule # CMP--6 from core.pose import PoseEstimator # CMP--9 from core.frontier import FrontierGenerator # CMP--2 from core.planner import PathPlanner # CMP--4 from core.goal_region import GoalRegionSelector # CMP--5 from core.motion_control import MotionController # CMP--8 from core.mission_control import MissionController # CMP--1 from core.exploration_status import ExplorationStatus # CMP--11 from core.events import EventQueue # DAT--7 from core.config import Config from Waveshare.battery import Battery from Waveshare.motor import Motor from Waveshare.ultrasonic_sensor import UltrasonicSensor from Waveshare.infrared import Infrared
def create_system(): """Initialize all modules and wire dependencies. Traces: CMP--10, CMP--1..CMP--11.""" config = Config()
# Hardware objects battery = Battery() motor_hw = Motor() ultrasonic = UltrasonicSensor() infrared = Infrared()
# Shared infra event_queue = EventQueue(size=16) # DAT--7 grid_map = GridMap(config=config) # CMP--3 pose = PoseEstimator(config=config) # CMP--9 sal = SensorAbstractionLayer( ultrasonic=ultrasonic, infrared=infrared, config=config, ) # CMP--7 mapping = MappingModule( grid_map=grid_map, config=config, ) # CMP--6 planner = PathPlanner( grid_map=grid_map, config=config, ) # CMP--4 frontier = FrontierGenerator( grid_map=grid_map, planner=planner, config=config, ) # CMP--2 goal_region = GoalRegionSelector( grid_map=grid_map, planner=planner, config=config, ) # CMP--5 motion = MotionController( motor=motor_hw, sal=sal, config=config, ) # CMP--8 exploration_status = ExplorationStatus( grid_map=grid_map, config=config, event_queue=event_queue, ) # CMP--11 mission = MissionController( grid_map=grid_map, frontier=frontier, planner=planner, goal_region=goal_region, motion=motion, exploration_status=exploration_status, sal=sal, pose=pose, event_queue=event_queue, config=config, ) # CMP--1
scheduler = Scheduler( config=config, sal=sal, grid_map=grid_map, mapping=mapping, mission=mission, planner=planner, motion=motion, pose=pose, exploration_status=exploration_status, ) # CMP--10
return scheduler, battery
def main(): scheduler, battery = create_system() # Simple blocking loop. In MicroPython this should be the only top-level loop. scheduler.run_forever()
if __name__ == "__main__": main()

"""
Grid Map Module.

Traces:
- CMP--3 Grid Map Module
- DAT--1 Grid Map Data Structures
"""

from core.types import CELL_UNKNOWN, CELL_FREE, CELL_BLOCKED
from core.types import WALL_UNKNOWN, WALL_PRESENT, WALL_ABSENT


class GridMap:
    """4x8 grid map with cell and wall classifications. (CMP--3, DAT--1)"""

    def __init__(self, config):
        self.config = config
        self.rows = config.rows
        self.cols = config.cols

        # DAT--1: cell and wall storage
        self.cells = [[CELL_UNKNOWN for _ in range(self.cols)] for _ in range(self.rows)]
        # Horizontal walls: between (row, col) and (row+1, col) => 3 x 8
        self.h_walls = [[WALL_UNKNOWN for _ in range(self.cols)] for _ in range(self.rows - 1)]
        # Vertical walls: between (row, col) and (row, col+1) => 4 x 7
        self.v_walls = [[WALL_UNKNOWN for _ in range(self.cols - 1)] for _ in range(self.rows)]

        self.unknown_cells_count = self.rows * self.cols
        # Approximate wall count: horizontal + vertical
        self.unknown_walls_count = (self.rows - 1) * self.cols + self.rows * (self.cols - 1)
        self.map_complete = False

        self.start_cell = (0, 0)

        self.init_map()

    # --- Initialization (CMP--3.Execution #1) ---

    def init_map(self):
        """Initialize cells and walls to UNKNOWN and start cell FREE."""
        for r in range(self.rows):
            for c in range(self.cols):
                self.cells[r][c] = CELL_UNKNOWN
        for r in range(self.rows - 1):
            for c in range(self.cols):
                self.h_walls[r][c] = WALL_UNKNOWN
        for r in range(self.rows):
            for c in range(self.cols - 1):
                self.v_walls[r][c] = WALL_UNKNOWN
        self.unknown_cells_count = self.rows * self.cols
        self.unknown_walls_count = (self.rows - 1) * self.cols + self.rows * (self.cols - 1)
        # Start cell FREE (CMP--3.Execution)
        sr, sc = self.start_cell
        self._set_cell_state(sr, sc, CELL_FREE)

    # --- Queries (CMP--3.Purpose) ---

    def in_bounds(self, row, col):
        return 0 &lt;= row &lt; self.rows and 0 &lt;= col &lt; self.cols

    def get_cell_state(self, row, col):
        if not self.in_bounds(row, col):
            return CELL_BLOCKED  # treat out-of-bounds as blocked
        return self.cells[row][col]

    def get_neighbors4(self, row, col):
        """Return list of in-bounds orthogonal neighbors (no wall consideration)."""
        res = []
        if row &gt; 0:
            res.append((row - 1, col))
        if row &lt; self.rows - 1:
            res.append((row + 1, col))
        if col &gt; 0:
            res.append((row, col - 1))
        if col &lt; self.cols - 1:
            res.append((row, col + 1))
        return res

    def _wall_index(self, row, col, nrow, ncol):
        """Return (orientation, r, c) for wall between (row,col) and (nrow,ncol)."""
        if row == nrow:
            # vertical wall between cols
            c = min(col, ncol)
            return ("V", row, c)
        elif col == ncol:
            # horizontal wall between rows
            r = min(row, nrow)
            return ("H", r, col)
        else:
            return (None, None, None)

    def get_wall_state_between(self, row, col, nrow, ncol):
        orient, r, c = self._wall_index(row, col, nrow, ncol)
        if orient is None:
            return WALL_PRESENT
        if orient == "H":
            return self.h_walls[r][c]
        else:
            return self.v_walls[r][c]

    # --- Updates enforcing invariants (CMP--3.Invariants) ---

    def _set_cell_state(self, row, col, new_state):
        """Internal: enforce UNKNOWN-&gt;FREE/BLOCKED only."""
        if not self.in_bounds(row, col):
            return
        old = self.cells[row][col]
        if old == new_state:
            return
        if old != CELL_UNKNOWN:
            # Invalid transition: ignore per CMP--3.Failures
            return
        if new_state not in (CELL_FREE, CELL_BLOCKED):
            return
        self.cells[row][col] = new_state
        self.unknown_cells_count -= 1
        self._update_map_completeness()

    def set_cell_free(self, row, col):
        self._set_cell_state(row, col, CELL_FREE)

    def set_cell_blocked(self, row, col):
        self._set_cell_state(row, col, CELL_BLOCKED)

    def _set_wall_state(self, orient, r, c, new_state):
        """Internal: enforce UNKNOWN-&gt;PRESENT/ABSENT only."""
        if orient == "H":
            if not (0 &lt;= r &lt; self.rows - 1 and 0 &lt;= c &lt; self.cols):
                return
            old = self.h_walls[r][c]
            if old != WALL_UNKNOWN or new_state not in (WALL_PRESENT, WALL_ABSENT):
                return
            self.h_walls[r][c] = new_state
        else:
            if not (0 &lt;= r &lt; self.rows and 0 &lt;= c &lt; self.cols - 1):
                return
            old = self.v_walls[r][c]
            if old != WALL_UNKNOWN or new_state not in (WALL_PRESENT, WALL_ABSENT):
                return
            self.v_walls[r][c] = new_state
        self.unknown_walls_count -= 1
        self._update_map_completeness()

    def set_wall_present_between(self, row, col, nrow, ncol):
        orient, r, c = self._wall_index(row, col, nrow, ncol)
        if orient is None:
            return
        self._set_wall_state(orient, r, c, WALL_PRESENT)

    def set_wall_absent_between(self, row, col, nrow, ncol):
        orient, r, c = self._wall_index(row, col, nrow, ncol)
        if orient is None:
            return
        self._set_wall_state(orient, r, c, WALL_ABSENT)

    def _update_map_completeness(self):
        """Maintain GM_MapCompletenessFlag (CMP--3.Execution #6)."""
        self.map_complete = (self.unknown_cells_count == 0 and self.unknown_walls_count == 0)

    def is_complete(self):
        return self.map_complete

"""
Path Planner.

Traces:
- CMP--4 Path Planner
- DAT--2 Traversal Cost Model Parameters
"""

from core.types import CELL_FREE, CELL_BLOCKED
from core.types import WALL_PRESENT


class PathPlanner:
    def __init__(self, grid_map, config):
        self.grid_map = grid_map
        self.config = config

    # --- Core graph helpers ---

    def _neighbors_free(self, cell):
        """Return neighboring FREE cells with no PRESENT wall between them."""
        (r, c) = cell
        res = []
        for (nr, nc) in self.grid_map.get_neighbors4(r, c):
            if self.grid_map.get_cell_state(nr, nc) != CELL_FREE:
                continue
            if self.grid_map.get_wall_state_between(r, c, nr, nc) == WALL_PRESENT:
                continue
            res.append((nr, nc))
        return res

    def _heuristic(self, a, b):
        """Manhattan heuristic for A* (CMP--4.Execution)."""
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def _edge_cost(self, prev, cur, nxt, mode):
        """
        Cost according to DAT--2:
        - baseStraightCost
        - turnPenalty when direction changes
        """
        if mode == "SECOND_RUN":
            base = self.config.second_run_straight_cost
            turn_penalty = self.config.second_run_turn_penalty
        else:
            base = self.config.exploration_straight_cost
            turn_penalty = self.config.exploration_turn_penalty

        if prev is None or cur is None or nxt is None:
            return base
        dr1 = cur[0] - prev[0]
        dc1 = cur[1] - prev[1]
        dr2 = nxt[0] - cur[0]
        dc2 = nxt[1] - cur[1]
        if dr1 == dr2 and dc1 == dc2:
            return base
        return base + turn_penalty

    # --- Public planning API (CMP--4.ConnectedComponents) ---

    def plan_single(self, start, goal, mode="EXPLORE", max_cost=None):
        """
        Plan path from start to single goal cell using A*.
        Returns (path:list[(r,c)], total_cost) or (None, None).
        """
        if self.grid_map.get_cell_state(start[0], start[1]) == CELL_BLOCKED:
            return None, None
        if self.grid_map.get_cell_state(goal[0], goal[1]) == CELL_BLOCKED:
            return None, None

        open_set = [start]
        came_from = {}
        g_score = {start: 0.0}
        f_score = {start: self._heuristic(start, goal)}

        while open_set:
            # Find node with smallest f
            current = None
            best_f = None
            for n in open_set:
                f = f_score.get(n, 1e9)
                if best_f is None or f &lt; best_f:
                    best_f = f
                    current = n

            if current == goal:
                return self._reconstruct_path(came_from, current), g_score[current]

            open_set.remove(current)
            neighbors = self._neighbors_free(current)
            for neighbor in neighbors:
                prev = came_from.get(current, None)
                tentative_g = g_score[current] + self._edge_cost(prev, current, neighbor, mode)
                if max_cost is not None and tentative_g &gt; max_cost:
                    continue
                if tentative_g &lt; g_score.get(neighbor, 1e9):
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score[neighbor] = tentative_g + self._heuristic(neighbor, goal)
                    if neighbor not in open_set:
                        open_set.append(neighbor)
        return None, None

    def _reconstruct_path(self, came_from, current):
        path = [current]
        while current in came_from:
            current = came_from[current]
            path.append(current)
        path.reverse()
        return path

"""
Goal Region Identification and Selection.

Traces:
- CMP--5 Goal Region Identification and Selection
"""

from core.types import CELL_FREE


class GoalRegionSelector:
    def __init__(self, grid_map, planner, config):
        self.grid_map = grid_map
        self.planner = planner
        self.config = config
        self.selected_region = None  # dict with 'cells', 'target_cell', 'cost'

    def select_region(self, start_cell):
        """
        Enumerate all 2x2 FREE regions and pick region with minimal path cost
        from start to any of its cells. (CMP--5.Execution)
        """
        best = None
        best_cost = None
        rows = self.grid_map.rows
        cols = self.grid_map.cols
        for r in range(rows - 1):
            for c in range(cols - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                if not all(self.grid_map.get_cell_state(cr, cc) == CELL_FREE for (cr, cc) in cells):
                    continue
                # For each candidate, request path cost using planner
                region_best_cost = None
                region_best_cell = None
                for (cr, cc) in cells:
                    path, cost = self.planner.plan_single(start_cell, (cr, cc), mode="SECOND_RUN")
                    if path:
                        if region_best_cost is None or cost &lt; region_best_cost:
                            region_best_cost = cost
                            region_best_cell = (cr, cc)
                if region_best_cost is None:
                    continue
                if best_cost is None or region_best_cost &lt; best_cost:
                    best_cost = region_best_cost
                    best = {
                        "cells": cells,
                        "target_cell": region_best_cell,
                        "cost": region_best_cost,
                    }
        self.selected_region = best
        return best
